<?php use App\Support\Ui; ?>
<div class="page-heading"><div><a class="back-link" href="<?= $e($url('candidate/interviews')) ?>">← My interviews</a><span class="eyebrow">INTERVIEW DETAILS</span><h1><?= $e($interview['company_name']) ?></h1><p><?= $e($interview['job_role']) ?> · <?= $e($interview['technology_name']) ?></p></div><span class="badge <?= $interview['status'] === 'CANCELLED' ? 'danger-badge' : 'green' ?>"><?= $e(ucfirst(strtolower($interview['status']))) ?></span></div>
<div class="detail-layout"><section class="card interview-detail-card"><div class="detail-hero"><span class="date-tile large"><strong><?= $e($interview['start_local']->format('d')) ?></strong><?= $e(strtoupper($interview['start_local']->format('M'))) ?></span><div><h2><?= $e($interview['display_date']) ?></h2><p><?= $e($interview['display_time']) ?> · <?= $e($interview['duration_minutes']) ?> minutes</p></div></div><dl class="detail-grid"><div><dt>Interview type</dt><dd><span class="badge <?= $interview['interview_type'] === 'TOOL' ? 'purple' : 'neutral' ?>"><?= $e(ucfirst(strtolower($interview['interview_type']))) ?></span></dd></div><div><dt>Interview round</dt><dd><?= $e($interview['interview_round']) ?></dd></div><div><dt>Technology</dt><dd><?= $e($interview['technology_name']) ?></dd></div><?php if($interview['support_person_name']): ?><div><dt>Support person</dt><dd><?= $e($interview['support_person_name']) ?></dd></div><?php endif; ?><div><dt>HR contact</dt><dd><?= $interview['hr_unavailable'] ? 'Details not available' : $e($interview['hr_name'] . ' · ' . $interview['hr_phone']) ?></dd></div><div><dt>Booking reference</dt><dd>#<?= $e($interview['id']) ?></dd></div></dl></section>
